parameters.functionCode:
// Handle Meta verification challenge
const query = $input.first().json.query || {};
if (query['hub.verify_token'] === $env.WHATSAPP_VERIFY_TOKEN) {
  return [{ json: { response: query['hub.challenge'] } }];
}
return [{ json: { response: 'Forbidden' } }];

const input = $input.first().json;
const body = input.body || input;

// Parse WhatsApp Cloud API webhook
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;

if (!value?.messages?.length) return [{ json: { skip: true } }];

const message = value.messages[0];
const contact = value.contacts?.[0];

return [{
  json: {
    message_id: message.id,
    from: message.from, // phone number
    contact_name: contact?.profile?.name || '',
    timestamp: message.timestamp,
    type: message.type, // text, image, document, etc.
    text: message.text?.body || '',
    media_id: message.image?.id || message.document?.id || null,
    is_reply: !!message.context,
    reply_to: message.context?.id || null
  }
}];

const contact = $input.first().json;
const message = $node['Parse Inbound Message'].json;

const isKnown = !!contact.id;
const contactId = contact.id || null;

// Simple intent detection
const text = message.text.toLowerCase();
let intent = 'general';
if (text.includes('harga') || text.includes('price') || text.includes('biaya')) intent = 'pricing';
else if (text.includes('demo') || text.includes('coba')) intent = 'demo_request';
else if (text.includes('bantuan') || text.includes('help') || text.includes('masalah')) intent = 'support';
else if (text.includes('berhenti') || text.includes('stop') || text.includes('unsubscribe')) intent = 'unsubscribe';

return [{
  json: {
    ...message,
    contact_id: contactId,
    contact_name_db: contact.first_name || message.contact_name,
    is_known_contact: isKnown,
    client_id: contact.client_id,
    intent: intent,
    needs_human: intent === 'support' || intent === 'unsubscribe'
  }
}];

